function categoriseGap(criteria) {
  const {patternIdentified,codeWithoutHelp,passedTests,testedEdgeCases,statedComplexity}=criteria;
  if(!patternIdentified) return 'pattern';
  if(!codeWithoutHelp||!passedTests) return 'implementation';
  if(!statedComplexity) return 'communication';
  if(!testedEdgeCases) return 'communication';
  return 'none';
}

function timeRemaining(elapsed, budget) {
  return Math.max(0, budget - elapsed);
}

